```json
{
  ...
  "autoApiService": {
    "id": 234857,
    "name": "Default API",
    "app_config": {
      "endpoint": "...",
      "db_schema": "public",
      "realtime_multitenant_enabled": true
    },
    "app": { "id": 1, "name": "Auto API" },
    "protocol": "https",
    "endpoint": "...",
    ...
  }
}
```

